Lemma evt_after : forall Q ms ms1, Exec.msteps asegs ms ms1 -> evt asegs Q ms1 -> evt asegs Q ms.
Proof. intros Q ms ms1 H (ms' & H' & HQ). exists ms'. split; [eapply Exec.msteps_trans; eassumption | exact HQ]. Qed.

Definition ASNP_STACK : Z := 6144.

(* [comment removed for export] *)
Definition snprintf_d_m1_stmt2 : Prop :=
  forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
         (F : bvmap 5 word) (fc : bv 32) (m : mem) (lo : Z) (junk : list byte),
    F = bvmap_empty -> fc = Z_to_bv 32 0 ->
    a1 = Z_to_bv 64 22 -> a2 = Z_to_bv 64 A_STR_FMT_D -> a3 = Z_to_bv 64 18446744073709551615 ->
    bv_unsigned a0 mod 64 = 32 ->
    bv_unsigned sp mod 16 = 0 -> bv_unsigned sp <= 0x7fffffffffc0 ->
    stk asegs m lo (bv_unsigned sp) -> aceil <= lo -> lo + ASNP_STACK <= bv_unsigned sp ->
    rw_cells asegs m (bv_unsigned a0) [CB 22 junk] ->
    aapp (bv_unsigned a0 - 32) 64 ->
    rw_cells asegs m (sh (bv_unsigned a0 - 32)) [C8 (wz SNP_HEAD)] ->
    SHAD m (bv_unsigned sp - ASNP_STACK) (poison_bytes 768 0) ->
    acanary m -> mem_inv asegs m -> ACONST m ->
    evt asegs (asnprintf_d_m1_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc a0 lo junk m)
      (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
          F (Z_to_bv 64 ASNPRINTF_STUB) fc None m (seg_rom asegs)).

Lemma firstn_skipn_repeat : forall {A} (x : A) n o k, (o + k <= n)%nat -> firstn k (skipn o (repeat x n)) = repeat x k.
Proof.
  intros A x n. induction n as [|n IH]; intros o k H.
  - assert (o = 0%nat) by lia. assert (k = 0%nat) by lia. subst. reflexivity.
  - destruct o as [|o].
    + destruct k as [|k]; [reflexivity|]. specialize (IH 0%nat k ltac:(lia)).
      change (firstn (S k) (skipn 0 (repeat x (S n)))) with (x :: firstn k (skipn 0 (repeat x n))). rewrite IH. reflexivity.
    + cbn [repeat skipn]. apply IH. lia.
Qed.

Lemma bytes_eq_of_Z : forall (l1 l2 : list byte), map (@bv_unsigned 8) l1 = map (@bv_unsigned 8) l2 -> l1 = l2.
Proof.
  induction l1 as [|x l1 IH]; intros [|y l2] H; cbn [map] in H; try discriminate; [reflexivity|].
  injection H as Hx Hl. f_equal; [apply bv_eq; exact Hx | apply IH; exact Hl].
Qed.
